     */
    protected void addHeaderParameters(HttpHeaders httpHeaders, GatewayContext context, Map<String, String> extendInfo){
        //头信息中添加参数
        if (extendInfo == null || !extendInfo.containsKey(AppServiceConstants.NO_SET_GATEWAY_PARAMETERS)) {
            GatewayContextUtil
                    .appMap(context)
                    .forEach((key, value) -> httpHeaders.set(key, value));
        }
    }

    /**
     * 是否添加参数曹url上
     * @param httpMethod
     * @param context
     * @return
     */
    protected boolean isAddParametersToUrl(HttpMethod httpMethod, GatewayContext context){
        if(HttpMethod.GET == httpMethod){
            return true;
        }

        //强制设置URL参数
        return Optional.ofNullable(context.getAppService().getExtendInfo())
                .map(map -> map.get(AppServiceConstants.ADD_URL_REQUEST_PARAMETERS))
                .map(v -> Boolean.valueOf(v))
                .map(v->BooleanUtil.isTrue(v))
                .orElse(false);
    }

    /**
     * 获取请求体
     *
     * @param httpHeaders
     * @param httpMethod
     * @param context
     * @param isAddParametersToUrl
     * @return
     */
    protected HttpEntity getHttpEntity(HttpHeaders httpHeaders, HttpMethod httpMethod, GatewayContext context, boolean isAddParametersToUrl, Map<String, String> extendInfo) {
        if (HttpMethod.GET == httpMethod) {
            return new HttpEntity(httpHeaders);
        }

        //请求参数不为空，使用参数提交
        Map<String, String> requestParam = context.getRequestParam();
        if (context.getRequestParam() != null && !requestParam.isEmpty() && !isAddParametersToUrl) {
            MultiValueMap multiValueMap = new LinkedMultiValueMap(requestParam.size());
            requestParam.forEach((k, v) -> multiValueMap.add(k, v != null ? v : ""));
            return new HttpEntity(multiValueMap, httpHeaders);
        }

        //无请求参数，则使用body提交
        return new HttpEntity(context.getRequestBody(), httpHeaders);
    }

    /**
     * 获取头信息
     *
     * @param context
     * @return
     */
    protected HttpHeaders getHeader(GatewayContext context) {
        HttpHeaders headers = new HttpHeaders();
        HttpServletRequest request = context.getHttpServletRequest();
        Enumeration<String> keys = request.getHeaderNames();
        while (keys.hasMoreElements()) {
            String key = keys.nextElement();
            if (!excludeHeadKeys.contains(key)) {
                headers.add(key, request.getHeader(key));
            }
        }
        return headers;
    }

    /**
     * 获取请求类型
     *
     * @param context
     * @return
     */
    protected HttpMethod getMethod(GatewayContext context) {
        return HttpMethod.resolve(context.getHttpServletRequest().getMethod());
    }

    /**
     * 获取结果类型
     *
     * @return
     */
    protected Class getResultType() {
        return String.class;
    }

    /**
     * 结果状态转换
     *
     * @param result
     * @param context
     */
    protected void resultStatusConvert(HttpResult result, GatewayContext context, Map<String, String> extendInfo) {
        if (result != null && !result.isSuccess()) {
            return;
        }
        String scriptId = extendInfo.get(AppServiceConstants.EXTERNAL_RESULT_HANDLE_SCRIPT_ID);
        ExternalServiceResultScriptProxy script = gatewayGroovyScriptFactory.getScript(scriptId, ExternalServiceResultScriptProxy.class);
        if (script != null) {
            script.handle(result, context, extendInfo);
        }
    }

    abstract RestTemplate getRestTemplate();
}

