import cn.com.cathayins.wireless.eclipse.gateway.common.constant.AppConstants;
import cn.com.cathayins.wireless.eclipse.gateway.common.constant.PipeLineConstants;
import cn.com.cathayins.wireless.eclipse.gateway.component.model.GatewayContext;
import org.apache.commons.lang3.StringUtils;
import org.springframework.http.HttpHeaders;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestTemplate;

import javax.annotation.Resource;
import javax.servlet.http.HttpServletRequest;

/**
 * http简单请求处理
 *
 * @author 致远
 * @date 2022/5/4 15:48
 */
@Component
public class HttpSimpleStrategyImpl extends AbstractHttpStrategy {

    private static final String AUTHORIZATION_HEADER = "Authorization";

    @Resource(name = "restTemplate")
    private RestTemplate restTemplate;

    @Override
    RestTemplate getRestTemplate() {
        return restTemplate;
    }

    @Override
    protected HttpHeaders getHeader(GatewayContext context) {
        HttpHeaders headers = super.getHeader(context);

        // SSO场景下，将Authorization信息透传到下游http header
        HttpServletRequest request = context.getHttpServletRequest();
        String userType = request.getHeader(PipeLineConstants.HEADER_KEY_USER_TYPE);
        if (AppConstants.SSO.equals(userType)) {
            String authorization = request.getHeader(AUTHORIZATION_HEADER);
            if (StringUtils.isNotBlank(authorization)) {
                headers.set("caToken", authorization);
            }
        }

        return headers;
    }
}

