@Component
@Slf4j
public class WirelessCoreClient {


    @Resource(name="restTemplate")
    private RestTemplate restTemplate;

    //无线核心
    @Value("${wireless.core.base.url}")
    private String wirelessCoreBaseUrl;

    private String graphqlService = "/graphql";
    private String graphqlResultDataKey = "data";
    private String graphqlResultErrorKey = "errors";
    private String respCodeKey  = "respCode";
    private String failCauseKey  = "failCause";
    private String restResultKey  = "content";
    private String successKey  = "success";
    private String errorMessageKey="errorMessage";
    private String errorPathKey="errorPath";

    public HttpResult restForGraphql(GatewayContext context, String requestBody) {
        return restForGraphqlByName(context, context.getServiceName(), requestBody);
    }

    public HttpResult restForGraphqlByName(GatewayContext context, String serviceName, String requestBody) {
        // 地址参数
        Map<String, String> urlParam = GatewayContextUtil.appMap(context, serviceName);

        // 请求地址
        UriComponentsBuilder uriComponentsBuilder = UriComponentsBuilder.fromHttpUrl(wirelessCoreBaseUrl + graphqlService);
        //设置URL参数
        if (urlParam != null && !urlParam.isEmpty()) {
            urlParam.forEach((key, value) -> {
                uriComponentsBuilder.queryParam(key, value != null ? value : "");
            });
        }

        String url = uriComponentsBuilder.toUriString();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON_UTF8);
        HttpEntity<String> formEntity = new HttpEntity<>(requestBody, headers);

        //响应结果
        String responseBody = null;
        try {
            responseBody = ResultUtils.call(() -> restTemplate.postForEntity(url, formEntity, String.class).getBody()
                    , () -> String.format("请求无线核心，地址：【%s】 报文【%s】", url, requestBody));
        } catch (GatewayNewException e) {
            return HttpResult.ofFailed(e.getErrorEnum());
        }

        JSONObject json = JSON.parseObject(responseBody);
        if (json.containsKey(graphqlResultErrorKey)) {
            JSONObject error = json.getJSONArray(graphqlResultErrorKey).getJSONObject(0);
            return HttpResult.ofFailedMsg(error.getString("code"), error.getString("message"));
        } else {
            return HttpResult.ofSuccess(json.get(graphqlResultDataKey));
        }
    }

    public HttpResult restForwardCommon(MultipartFile file, Map<String, String> requestUrlParams, String url) {
        //拼装请求url
        UriComponentsBuilder uriComponentsBuilder = UriComponentsBuilder.fromHttpUrl(url);

        //构建请求
        HttpEntity<MultiValueMap<String, Object>> requestEntity = buildRequestEntity(file, requestUrlParams);

        String responseBody = null;

        try{
            responseBody = ResultUtils.call(() -> restTemplate.postForEntity(uriComponentsBuilder.toUriString(), requestEntity, String.class).getBody()
                    , () -> String.format("请求无线核心，地址：【%s】 报文【%s】", uriComponentsBuilder.toUriString(), JSON.toJSONString(requestUrlParams)));
        }catch (GatewayNewException e){
            return HttpResult.ofFailed(e.getErrorEnum());
        }

        JSONObject json = JSON.parseObject(responseBody);

        // success == true
        if (null != json.getBoolean(successKey) && json.getBoolean(successKey)) {
            return HttpResult.ofSuccess(null != json.get(restResultKey) ? json.get(restResultKey) : json.get(graphqlResultDataKey));
        }

        // success == false
        // 1.兼容 Response
        if (null != json.getString(respCodeKey)) {
            return HttpResult.ofFailedMsg(json.getString(respCodeKey), json.getString(failCauseKey));
        }

        // 2.兼容 GenericRpcResponse
        if (json.containsKey(graphqlResultErrorKey) && null != json.getJSONArray(graphqlResultErrorKey) && !json.getJSONArray(graphqlResultErrorKey).isEmpty()) {
            JSONObject error = json.getJSONArray(graphqlResultErrorKey).getJSONObject(0);
            return HttpResult.ofFailedMsg(error.getString(errorPathKey), null != error.getString(errorMessageKey) ? error.getString(errorMessageKey) : ResultCodeEnum.ERROR.getMsg());
        }

        // 3.兼容以上没取到的情况
        return HttpResult.ofFailedMsg(ResultCodeEnum.ERROR.getCode(), ResultCodeEnum.ERROR.getMsg());
    }

    public HttpResult restForward(MultipartFile file, Map<String, String> requestUrlParams, String url) {
        return doRestForward(file, requestUrlParams, url, restTemplate);
    }

    public HttpResult restForward(MultipartFile file, GatewayContext context) {
        // 获取超时时间
        Integer routeTimeout = getRouteTimeOut(context);
        // 存在超时时间
        if (routeTimeout != null && routeTimeout > 0) {
            return doRestForward(file, context.getRequestParam(), context.getUrlSurfix(), buildCustomTimeoutRestTemplate(routeTimeout));
        }

        return restForward(file, context.getRequestParam(), context.getUrlSurfix());
    }

    public HttpResult restForwardFiles(List<MultipartFile> files, Map<String, String> requestUrlParams, String url) {
        return doRestForward(files, requestUrlParams, url, restTemplate);
    }

    public HttpResult restForwardFiles(List<MultipartFile> files, GatewayContext context) {
        // 获取超时时间
        Integer routeTimeout = getRouteTimeOut(context);
        // 存在超时时间
        if (routeTimeout != null && routeTimeout > 0) {
            return doRestForward(files, context.getRequestParam(), context.getUrlSurfix(), buildCustomTimeoutRestTemplate(routeTimeout));
        }

        return restForwardFiles(files, context.getRequestParam(), context.getUrlSurfix());
    }

    private HttpResult doRestForward(MultipartFile file, Map<String, String> requestUrlParams, String url, RestTemplate restTemplate) {
        //拼装请求url
        UriComponentsBuilder uriComponentsBuilder = UriComponentsBuilder.fromHttpUrl(wirelessCoreBaseUrl + "/" + url);

        //构建请求
        HttpEntity<MultiValueMap<String, Object>> requestEntity = buildRequestEntity(file, requestUrlParams);

        String responseBody = null;

        try {
            responseBody = ResultUtils.call(() -> restTemplate.postForEntity(uriComponentsBuilder.toUriString(), requestEntity, String.class).getBody()
                    , () -> String.format("请求无线核心，地址：【%s】 报文【%s】", uriComponentsBuilder.toUriString(), JSON.toJSONString(requestUrlParams)));
        } catch (GatewayNewException e) {
            return HttpResult.ofFailed(e.getErrorEnum());
        }

        JSONObject json = JSON.parseObject(responseBody);

        // success == true
        if (null != json.getBoolean(successKey) && json.getBoolean(successKey)) {
            return HttpResult.ofSuccess(null != json.get(restResultKey) ? json.get(restResultKey) : json.get(graphqlResultDataKey));
        }

        // success == false
        // 1.兼容 Response
        if (null != json.getString(respCodeKey)) {
            return HttpResult.ofFailedMsg(json.getString(respCodeKey), json.getString(failCauseKey));
        }

        // 2.兼容 GenericRpcResponse
        if (json.containsKey(graphqlResultErrorKey) && null != json.getJSONArray(graphqlResultErrorKey) && !json.getJSONArray(graphqlResultErrorKey).isEmpty()) {
            JSONObject error = json.getJSONArray(graphqlResultErrorKey).getJSONObject(0);
            return HttpResult.ofFailedMsg(error.getString(errorPathKey), null != error.getString(errorMessageKey) ? error.getString(errorMessageKey) : ResultCodeEnum.ERROR.getMsg());
        }

        // 3.兼容以上没取到的情况
        return HttpResult.ofFailedMsg(ResultCodeEnum.ERROR.getCode(), ResultCodeEnum.ERROR.getMsg());
    }

    private HttpResult doRestForward(List<MultipartFile> files, Map<String, String> requestUrlParams, String url, RestTemplate restTemplate) {
        //拼装请求url
        UriComponentsBuilder uriComponentsBuilder = UriComponentsBuilder.fromHttpUrl(wirelessCoreBaseUrl + "/" + url);

        //构建请求(批量文件以 files 字段名重复提交)
        HttpEntity<MultiValueMap<String, Object>> requestEntity = buildRequestEntity(files, requestUrlParams);

        String responseBody = null;

        try {
            responseBody = ResultUtils.call(() -> restTemplate.postForEntity(uriComponentsBuilder.toUriString(), requestEntity, String.class).getBody()
                    , () -> String.format("请求无线核心，地址：【%s】 报文【%s】", uriComponentsBuilder.toUriString(), JSON.toJSONString(requestUrlParams)));
        } catch (GatewayNewException e) {
            return HttpResult.ofFailed(e.getErrorEnum());
        }

        JSONObject json = JSON.parseObject(responseBody);

        // success == true
        if (null != json.getBoolean(successKey) && json.getBoolean(successKey)) {
            return HttpResult.ofSuccess(null != json.get(restResultKey) ? json.get(restResultKey) : json.get(graphqlResultDataKey));
        }

        // success == false
        // 1.兼容 Response
        if (null != json.getString(respCodeKey)) {
            return HttpResult.ofFailedMsg(json.getString(respCodeKey), json.getString(failCauseKey));
        }

        // 2.兼容 GenericRpcResponse
        if (json.containsKey(graphqlResultErrorKey) && null != json.getJSONArray(graphqlResultErrorKey) && !json.getJSONArray(graphqlResultErrorKey).isEmpty()) {
            JSONObject error = json.getJSONArray(graphqlResultErrorKey).getJSONObject(0);
            return HttpResult.ofFailedMsg(error.getString(errorPathKey), null != error.getString(errorMessageKey) ? error.getString(errorMessageKey) : ResultCodeEnum.ERROR.getMsg());
        }

        // 3.兼容以上没取到的情况
        return HttpResult.ofFailedMsg(ResultCodeEnum.ERROR.getCode(), ResultCodeEnum.ERROR.getMsg());
    }

    /**
     * 获取路由超时时间：当扩展信息中配置useRouteTimeOut=Y，且路由超时时间非空时返回超时值，否则返回null
     */
    private Integer getRouteTimeOut(GatewayContext context) {
        Map<String, String> extendInfo = context.getAppService().getExtendInfo();
        if (extendInfo == null || !"Y".equals(extendInfo.get(AppServiceConstants.USE_ROUTE_TIME_OUT))) {
            return null;
        }

        String httpMethod = context.getHttpServletRequest().getMethod();
        Map<String, RoutingVO> routingMap = context.getAppService().getRoutingMap();
        if (routingMap == null) {
            return null;
        }

        RoutingVO routingVO = routingMap.get(httpMethod);
        if (routingVO == null || routingVO.getTimeOut() == null) {
            return null;
        }

        return routingVO.getTimeOut();
    }

    /**
     * 创建自定义超时的独立RestTemplate，复用原始HttpClient连接池
     */
    private RestTemplate buildCustomTimeoutRestTemplate(int readTimeout) {
        ClientHttpRequestFactory factory = restTemplate.getRequestFactory();
        // 如果设置了拦截器，Spring会将RequestFactory包装为InterceptingClientHttpRequestFactory，需要解包
        if (factory instanceof InterceptingClientHttpRequestFactory) {
            Field field = ReflectionUtils.findField(InterceptingClientHttpRequestFactory.class, "requestFactory");
            field.setAccessible(true);
            factory = (ClientHttpRequestFactory) ReflectionUtils.getField(field, factory);
        }
        HttpComponentsClientHttpRequestFactory newFactory = new HttpComponentsClientHttpRequestFactory(((HttpComponentsClientHttpRequestFactory) factory).getHttpClient());
        // 同步其他超时配置
        newFactory.setConnectTimeout(4000);
        newFactory.setConnectionRequestTimeout(3000);
        newFactory.setReadTimeout(readTimeout);

        RestTemplate customRestTemplate = new RestTemplate(restTemplate.getMessageConverters());
        customRestTemplate.setRequestFactory(newFactory);
        customRestTemplate.setInterceptors(restTemplate.getInterceptors());
        return customRestTemplate;
    }


    private HttpEntity<MultiValueMap<String, Object>> buildRequestEntity(MultipartFile file, Map<String, String> requestUrlParams){
        //参数
        MultiValueMap<String, Object> params = new LinkedMultiValueMap<>();
        requestUrlParams.forEach(params::add);

        //文件参数
        if (null != file) {
            try {
                InputStreamResource fileResource = new InputStreamResource(file.getInputStream()) {
                    @Override
                    public long contentLength() {
                        return file.getSize();
                    }

                    @Override
                    public String getFilename() {
                        return file.getOriginalFilename();
                    }
                };
                params.add("file", fileResource);
            } catch (Exception e) {
                log.error("文件转换异常", e);
            }
        }

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.MULTIPART_FORM_DATA);
        HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(params, headers);
        return requestEntity;
    }

    /**
     * 批量文件转发的请求实体构建：多文件以 files 字段名重复提交，
     * 下游以 List<MultipartFile> / MultipartFile[] 接收。
     */
    private HttpEntity<MultiValueMap<String, Object>> buildRequestEntity(List<MultipartFile> files, Map<String, String> requestUrlParams){
        //参数
        MultiValueMap<String, Object> params = new LinkedMultiValueMap<>();
        requestUrlParams.forEach(params::add);

        //批量文件参数
        if (null != files && !files.isEmpty()) {
            for (MultipartFile item : files) {
                if (null == item || item.isEmpty()) {
                    continue;
                }
                final MultipartFile file = item;
                try {
                    InputStreamResource fileResource = new InputStreamResource(file.getInputStream()) {
                        @Override
                        public long contentLength() {
                            return file.getSize();
                        }

                        @Override
                        public String getFilename() {
                            return file.getOriginalFilename();
                        }
                    };
                    params.add("files", fileResource);
                } catch (Exception e) {
                    log.error("文件转换异常", e);
                }
            }
        }

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.MULTIPART_FORM_DATA);
        HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(params, headers);
        return requestEntity;
    }
}
